package org.example.post;

// 13-1 지금 상태에서는 바꿀 수 없는 글(임시저장을 숨기기·복구) — 전역 핸들러가 409로 변환한다
public class PostStatusConflictException extends RuntimeException {

    public PostStatusConflictException(String message) {
        super(message);
    }
}

